<?php
require_once __DIR__.'/includes/bootstrap.php'; require_auth();
if(role()!=='admin') { http_response_code(403); exit('Accès réservé à l’administrateur.'); }
$page_title='Gestion du stock'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??'';
 try {
  if($action==='product') { $name=trim($_POST['libelle']??''); $unit=trim($_POST['unite']??''); $threshold=(float)($_POST['seuil_min']??0); $cost=(float)($_POST['cout_moyen']??0); if($name===''||$unit===''||$threshold<0||$cost<0) throw new Exception('Vérifiez les champs du produit.'); $s=$pdo->prepare('INSERT INTO produits_stock(libelle,unite,seuil_min,cout_moyen) VALUES(?,?,?,?)'); $s->execute([$name,$unit,$threshold,$cost]); flash('Produit ajouté au stock.'); }
  elseif($action==='alert_done') { $pdo->prepare("UPDATE alertes_stock SET etat='traitee' WHERE id=?")->execute([(int)$_POST['alert_id']]); flash('Alerte marquée comme traitée.'); }
  elseif($action==='movement') { $id=(int)$_POST['product_id']; $type=$_POST['type']??''; $qty=(float)($_POST['quantite']??0); $reason=trim($_POST['motif']??''); if($id<1||$qty<=0||!in_array($type,['entree','sortie','ajustement'],true)) throw new Exception('Mouvement invalide.'); $s=$pdo->prepare('SELECT quantite_stock FROM produits_stock WHERE id=? FOR UPDATE'); $pdo->beginTransaction(); $s->execute([$id]); $current=$s->fetchColumn(); if($current===false) throw new Exception('Produit introuvable.'); if($type==='sortie' && $qty>(float)$current) throw new Exception('Stock insuffisant : disponible '.number_format((float)$current,2,',',' ').'.'); $s=$pdo->prepare('INSERT INTO mouvements_stock(produit_id,type,quantite,motif,utilisateur_id) VALUES(?,?,?,?,?)'); $s->execute([$id,$type,$qty,$reason,$_SESSION['user']['id']]); $pdo->commit(); flash('Mouvement de stock enregistré.'); }
 } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); flash($e->getMessage(),'error'); }
 redirect('stock.php');
}
$products=$pdo->query('SELECT * FROM produits_stock ORDER BY libelle')->fetchAll(); $movements=$pdo->query('SELECT m.*,p.libelle,u.nom AS name FROM mouvements_stock m JOIN produits_stock p ON p.id=m.produit_id LEFT JOIN utilisateurs u ON u.id=m.utilisateur_id ORDER BY m.id DESC LIMIT 30')->fetchAll(); $alerts=$pdo->query("SELECT a.*,p.libelle,p.quantite_stock,p.seuil_min FROM alertes_stock a JOIN produits_stock p ON p.id=a.produit_id WHERE a.etat='ouverte' ORDER BY a.id DESC")->fetchAll(); require 'includes/header.php'; ?>
<div class="cards"><div class="stat"><div class="label">Références actives</div><strong><?=count($products)?></strong></div><div class="stat"><div class="label">Alertes ouvertes</div><strong><?=count($alerts)?></strong></div><div class="stat"><div class="label">Produits sous le seuil</div><strong><?=count(array_filter($products,fn($x)=>$x['quantite_stock']<=$x['seuil_min']))?></strong></div></div>
<div class="panel"><h2>Ajouter un produit</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="product"><div class="field"><label>Nom du produit</label><input name="libelle" required placeholder="Lessive professionnelle"></div><div class="field"><label>Unité</label><select name="unite"><option>kg</option><option>litre</option><option>paquet</option><option>piece</option><option>bidon</option></select></div><div class="field"><label>Seuil minimum</label><input type="number" step="0.01" min="0" name="seuil_min" value="0" required></div><div class="field"><label>Coût moyen (FCFA)</label><input type="number" step="1" min="0" name="cout_moyen" value="0" required></div><div class="field full"><button class="btn">＋ Ajouter le produit</button></div></form></div>
<div class="panel"><h2>Enregistrer un mouvement</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="movement"><div class="field"><label>Produit</label><select name="product_id" required><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['libelle'])?> — <?=e($x['quantite_stock'].' '.$x['unite'])?></option><?php endforeach;?></select></div><div class="field"><label>Type de mouvement</label><select name="type"><option value="entree">Entrée</option><option value="sortie">Sortie / consommation</option><option value="ajustement">Ajustement (nouveau stock)</option></select></div><div class="field"><label>Quantité</label><input type="number" min="0.01" step="0.01" name="quantite" required></div><div class="field"><label>Motif</label><input name="motif" placeholder="Achat, utilisation, inventaire…"></div><div class="field full"><button class="btn green">Enregistrer le mouvement</button></div></form><p class="notice">Pour un ajustement, indiquez la quantité totale réellement présente après inventaire. Les sorties supérieures au stock disponible sont refusées.</p></div>
<div class="panel"><h2>Alertes de réapprovisionnement</h2><div class="table-wrap"><table><thead><tr><th>Produit</th><th>Stock actuel</th><th>Seuil</th><th>Action</th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td><?=e($a['libelle'])?></td><td><?=e($a['quantite_stock'])?></td><td><?=e($a['seuil_min'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="alert_done"><input type="hidden" name="alert_id" value="<?=$a['id']?>"><button class="btn small">Marquer traitée</button></form></td></tr><?php endforeach;?><?php if(!$alerts):?><tr><td colspan="4" class="empty">Aucune alerte ouverte.</td></tr><?php endif;?></tbody></table></div></div>
<div class="panel"><h2>État du stock</h2><div class="table-wrap"><table><thead><tr><th>Produit</th><th>Unité</th><th>Disponible</th><th>Seuil minimum</th><th>Coût moyen</th><th>État</th></tr></thead><tbody><?php foreach($products as $x):?><tr><td><?=e($x['libelle'])?></td><td><?=e($x['unite'])?></td><td><b><?=e($x['quantite_stock'])?></b></td><td><?=e($x['seuil_min'])?></td><td><?=money($x['cout_moyen'])?></td><td><?=$x['quantite_stock']<=$x['seuil_min']?'<span class="badge" style="background:#fee2e2;color:#991b1b">À réapprovisionner</span>':'<span class="badge pret">Disponible</span>'?></td></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="6" class="empty">Aucun produit enregistré.</td></tr><?php endif;?></tbody></table></div></div>
<div class="panel"><h2>Derniers mouvements</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Produit</th><th>Type</th><th>Quantité</th><th>Motif</th><th>Utilisateur</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e($m['date_mouvement'])?></td><td><?=e($m['libelle'])?></td><td><?=e(ucfirst($m['type']))?></td><td><?=e($m['quantite'])?></td><td><?=e($m['motif'])?></td><td><?=e($m['name']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require 'includes/footer.php'; ?>